        authorization = (
            session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=apply_started,
                expected_action="apply_committed",
            )
        )
        skipped = dict(recovery)
        skipped.pop("content_sha256")
